from cyclopts import App

app = App("calculator")

@app.command
def add(a: int, b: int) -> int:
    """Add two numbers."""
    return a + b

@app.command
def multiply(a: int, b: int) -> int:
    """Multiply two numbers."""
    return a * b

tokens = ["add", "2", "3"]
func, bound_args, ignored = app.parse_args(tokens, exit_on_error=False)

print(f"Command function name: {func.__name__}")
